function parseLedger(markdown) {
  // The archive may include a working-copy/decoy ledger; use the last canonical ledger section.
  const start = markdown.lastIndexOf("## Transaction Ledger\n");
  if (start < 0) {
    // Fallback to last occurrence of the heading without requiring trailing newline.
    const alt = markdown.lastIndexOf("## Transaction Ledger");
    if (alt < 0) return [];
    return parseLedger(markdown.slice(alt));
  }

  const slice = markdown.slice(start);
  const blocks = slice.split(/^### /m).slice(1);

  // Policy (per archive notes):
  // - Ignore any ledger block that includes a line `provisional: true` (case-insensitive)
  // - If multiple non-provisional blocks exist for the same transaction_id, the last
  //   such block in file order is the base row.
  const byId = new Map();

  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = (lines[0] || "").trim();
    if (!transactionId.startsWith("TXN-")) continue;

    const row = { transaction_id: transactionId };
    let provisional = false;

    for (const line of lines) {
      const trimmed = String(line).trim();
      if (trimmed.startsWith("amount:")) {
        row.amount = Number(trimmed.split(":")[1].trim());
      } else if (trimmed.startsWith("owner:")) {
        row.owner = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("status:")) {
        row.status = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("date:")) {
        row.date = trimmed.split(":")[1].trim();
      } else if (/^provisional\s*:\s*true\s*$/i.test(trimmed)) {
        provisional = true;
      }
    }

    if (provisional) continue;
    byId.set(transactionId, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
EOF
