const { sortByTransactionId } = require("../utils/sort");

// Status precedence from lowest to highest (Brief 02):
// pending < approved < rejected < reversed
const STATUS_RANK = {
  pending: 0,
  approved: 1,
  rejected: 2,
  reversed: 3,
};

function pickStatus(current, candidate) {
  const c = String(current || "").toLowerCase();
  const n = String(candidate || "").toLowerCase();
  if (!(n in STATUS_RANK)) return c;
  if (!(c in STATUS_RANK)) return n;
  return STATUS_RANK[n] > STATUS_RANK[c] ? n : c;
}

function getFieldValue(row, field) {
  if (field === "owner") return row.owner ?? "";
  if (field === "status") return row.status ?? "";
  if (field === "date") return row.date ?? "";
  return row[field] ?? "";
}

function setFieldValue(row, field, value) {
  if (field === "owner") row.owner = value;
  else if (field === "status") row.status = value;
  else if (field === "date") row.date = value;
  else row[field] = value;
}

function reconcileTransactions(parsed) {
  const byId = new Map();

  // 1) Base rows from canonical ledger
  for (const row of parsed.ledger || []) {
    byId.set(row.transaction_id, { ...row });
  }

  // 2) Meeting amendments (Brief 05): apply only signed amendments
  for (const amend of parsed.meetings || []) {
    const target = byId.get(amend.transaction_id);
    if (!target) continue;
    if (amend.signed && amend.owner) {
      target.owner = amend.owner;
    }
  }

  // 3) Mail-driven status changes (Brief 02):
  // apply only when From contains `compliance@` anywhere.
  // Merge by precedence (never downgrade).
  for (const email of parsed.emails || []) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;
    if (!String(email.from_addr || "").includes("compliance@")) continue;
    target.status = pickStatus(target.status, email.status);
  }

  // 4) Corrections (Brief 04 ordering details TBD by full briefs): apply deterministically
  const notices = [...(parsed.corrections || [])].sort((a, b) => {
    const ea = String(a.effective || "");
    const eb = String(b.effective || "");
    if (ea !== eb) return ea < eb ? -1 : 1;
    if (a.notice_id === b.notice_id) return 0;
    return a.notice_id < b.notice_id ? -1 : 1;
  });

  const report = [];
  for (const notice of notices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const prev = String(getFieldValue(target, notice.field));
    setFieldValue(target, notice.field, notice.value);

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: prev,
      new_value: String(notice.value),
      effective: notice.effective,
    });
  }

  // 5) Exception flags
  const policyExceptions = parsed.policyExceptions || new Set();

  const items = sortByTransactionId(
    [...byId.values()].map((row) => {
      const flags = [];
      if (policyExceptions.has(row.transaction_id)) flags.push("policy_exception");

      flags.sort();
      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status: String(row.status).toLowerCase(),
        effective_date: row.date,
        amount_usd: Number(Number(row.amount).toFixed(2)),
        exception_reason: flags.length ? flags.join(";") : null,
      };
    }),
  );

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_RANK };
EOF
