  const start = markdown.indexOf("## Correction Notices");
  if (start < 0) return [];

  // Corrections run until the next top-level section (Transaction Ledger).
  const end = markdown.indexOf("## Transaction Ledger", start);
  const slice = end > start ? markdown.slice(start, end) : markdown.slice(start);

  const notices = [];
